galj(){return"Play the whole piece"},
gb3W(){return"Tap a block to hear that section."},
galH(){return"See the harmony"},
gb50(){return"Tap a chord to hear it."},
gQ_(){return"Home (tonic)"},
gPZ(){return"Away (subdominant)"},
gPY(){return"Tension (dominant)"},
gb4n(){return"Home"},
gb4m(){return"Away"},
gb4l(){return"Tension"},
gaRI(){return"Harmony"},
gaRS(){return"Analyse the harmony"},
gDg(){return"Inspect (tap a note)"},
gaRH(){return"Form"},
gaRD(){return"Circle of fifths"},
gaRQ(){return"Tension"},
gahE(){return"Voice leading"},
gaRR(){return"No parallel 5ths or 8ves \u2713"},
gaRO(){return"Parallel fifths"},
gaRP(){return"Parallel octaves"},
gahD(){return"Non-chord tones"},
